contracts/interfaces/IInspector.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.22;

/**
 * @title IInspector
 * @notice Interface for the Messaging Inspector, allowing examination of message and options contents.
 */
interface IInspector {
    // @dev Custom error messages
    error InspectionFailed(bytes message, bytes options);
    error GlobalPausedIdempotent(bool paused);
    error IdPausedIdempotent(bytes32 id, bool paused);
    error GlobalPaused();
    error IdPaused(bytes32 id);

    // @dev Events
    event GlobalPausedSet(bool paused);
    event IdPausedSet(bytes32 id, bool paused);

    /**
     * @notice Sets the global paused value.
     * @param paused The state of the global pause.
     * @dev Sets a global pause state applied to all messages that are inspected.
     */
    function setGlobalPaused(bool paused) external;

    /**
     * @notice Sets the id paused value.
     * @param id The identifier.
     * @param paused The state of the pause.
     * @dev Sets the pause state for a given 'id'.
     */
    function setIdPaused(bytes32 id, bool paused) external;

    /**
     * @notice Allows the inspectee to examine LayerZero message contents and optionally throw a revert if invalid.
     * @param id The identifier being inspected.
     * @param message The message payload to be inspected.
     * @param options Additional options or parameters for inspection.
     */
    function inspect(bytes32 id, bytes calldata message, bytes calldata options) external view;
}

contracts/interfaces/IMessenger.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.22;

import { IOAppCore } from "@layerzerolabs/oapp-evm/contracts/oapp/interfaces/IOAppCore.sol";
import { MessagingFee, MessagingReceipt } from "@layerzerolabs/oft-evm/contracts/interfaces/IOFT.sol";

/**
 * @notice Struct representing messaging parameters for the Messenger send() operation.
 */
struct MessagingParam {
    uint32 dstEid; // Destination endpoint ID.
    bytes32 to; // Recipient address.
    uint256 amountLD; // Amount to send in local decimals.
    bytes extraOptions; // Additional options supplied by the caller to be used in the LayerZero message.
    bytes composeMsg; // The composed message for the send() operation.
}

/**
 * @title IMessenger
 * @notice Interface for the Messenger, the OApp responsible for routing OFT messages cross-chain.
 */
interface IMessenger is IOAppCore {
    // @dev Custom error messages
    error InvalidTokenRegistration(bytes32 tokenId, address tokenAddress);
    error InvalidTokenRegistrationWithOFT(bytes32 tokenId, address tokenAddress, address oftAddress);
    error TokenAlreadyRegistered(bytes32 tokenId, address tokenAddress);
    error TokenNotRegistered(bytes32 tokenId);
    error OFTAlreadyRegistered(address oftAddress, bytes32 existingTokenId);
    error InvalidOFT(address oft);
    error InvalidTokenId(bytes32 tokenId);
    error InvalidRateLimiter();

    // @dev Events
    event InspectorSet(address inspector);
    event RateLimiterSet(address rateLimiter);
    event TokenRegistered(bytes32 indexed tokenId, address indexed tokenAddress, address indexed oftAddress);
    event TokenDeregistered(bytes32 indexed tokenId, address indexed tokenAddress, address indexed oftAddress);

    // @dev Interface functions for the token detail mappings
    function idToOft(bytes32 tokenId) external view returns (address oftAddress);
    function idToToken(bytes32 tokenId) external view returns (address tokenAddress);
    function oftToId(address oftAddress) external view returns (bytes32 tokenId);

    /**
     * @notice Sets the inspector address, which is used to inspect messages before they are sent.
     * @param inspector The address of the inspector contract.
     * @dev This can be set to address(0) if no inspector is required.
     */
    function setInspector(address inspector) external;

    /**
     * @notice Sets the rate limiter address, which is used to validate inflows and outflows of tokens.
     * @param rateLimiter The address of the rate limiter contract.
     */
    function setRateLimiter(address rateLimiter) external;

    /**
     * @notice Registers a new token with its corresponding generated OFT contract.
     * @param tokenId The unique identifier for the token.
     * @param tokenAddress The address of the token contract.
     * @return oftAddress The address of the newly created OndoOFT contract.
     *
     * @dev This function is more limited in that it can only register a brand new tokenId, it cannot alter existing.
     */
    function registerToken(bytes32 tokenId, address tokenAddress) external returns (address oftAddress);

    /**
     * @notice Deregisters an existing token and clears all associated mappings.
     * @param tokenId The unique identifier for the token to be deregistered.
     *
     * @dev This function completely removes the token from all mappings, making it no longer usable.
     */
    function deregisterToken(bytes32 tokenId) external;

    /**
     * @notice Registers a token with an existing OFT contract address.
     * @param tokenId The unique identifier for the token.
     * @param tokenAddress The address of the token contract.
     * @param oftAddress The address of the existing OFT contract.
     *
     * @dev This function allows registering with a pre-existing OFT contract instead of creating a new one.
     * @dev Useful for fixing registration mistakes or migrating to new OFT contracts.
     */
    function registerTokenWithOFT(bytes32 tokenId, address tokenAddress, address oftAddress) external;

    /**
     * @notice Provides rate limit available for sending and receiving tokens by routing the call to the rateLimiter.
     * @param _tokenId The identifier for which the rate limit is being checked.
     * @param _tokenAddress The address of the token from the corresponding Id.
     * @param _remoteEid The remote endpoint id.
     * @return sendable The current amount that can be sent.
     * @return currentOutbound The current amount used for outbound flows.
     * @return receivable The amount that can be received.
     * @return currentInbound The current amount used for inbound flows.
     */
    function getRateLimitedAmounts(
        bytes32 _tokenId,
        address _tokenAddress,
        uint32 _remoteEid
    ) external view returns (uint256 sendable, uint256 currentOutbound, uint256 receivable, uint256 currentInbound);

    /**
     * @notice Provides a quote for the send() operation.
     * @param messagingParam The parameters for the send() operation.
     * @param payInLzToken Flag indicating whether the caller is paying in the LZ token.
     * @return msgFee The calculated LayerZero messaging fee from the send() operation.
     *
     * @dev MessagingFee: LayerZero msg fee
     *  - nativeFee: The native fee.
     *  - lzTokenFee: The lzToken fee.
     */
    function quoteSend(
        MessagingParam calldata messagingParam,
        bool payInLzToken
    ) external view returns (MessagingFee memory msgFee);

    /**
     * @notice Executes and routes the send function through the endpoint.
     * @param messagingParam The parameters for the send() operation.
     * @param fee The calculated fee for the send() operation.
     *      - nativeFee: The native fee.
     *      - lzTokenFee: The lzToken fee.
     * @param refundAddress The address to receive any excess funds.
     * @return msgReceipt The receipt for the send operation.
     *
     * @dev Since this is an external version, MUST index on the msg.sender to verify it's a valid OFT calling this.
     *
     * @dev MessagingReceipt: LayerZero msg receipt
     *  - guid: The unique identifier for the sent message.
     *  - nonce: The nonce of the sent message.
     *  - fee: The LayerZero fee incurred for the message.
     */
    function send(
        MessagingParam calldata messagingParam,
        MessagingFee calldata fee,
        address refundAddress
    ) external payable returns (MessagingReceipt memory msgReceipt);
}

contracts/interfaces/IOndoOFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.22;

import { Origin } from "@layerzerolabs/oapp-evm/contracts/oapp/OApp.sol";

// @dev Disabling unused, because we want to pipe down the structs so we ensure correct ones are used.
// solhint-disable no-unused-import
import { IOFT, SendParam, MessagingFee, MessagingReceipt, OFTLimit, OFTFeeDetail, OFTReceipt } from "@layerzerolabs/oft-evm/contracts/interfaces/IOFT.sol";

/**
 * @title IOndoOFT
 * @notice Interface for the Ondo OFT, which extends the LayerZero OFT interface.
 * @dev This interface is used for handling cross-chain messaging and operations then routing to the Messenger contract.
 */
interface IOndoOFT is IOFT {
    // @dev Custom error messages
    error OnlyMessenger(address messenger);
    error EndpointMismatch(address actualEndpoint, address expectedEndpoint);

    // @dev Events
    event MessengerSet(address indexed messenger);

    /**
     * @notice The unique identifier for this token in the bridge system.
     * @return The token ID as a bytes32 value.
     */
    function tokenId() external view returns (bytes32);

    /**
     * @notice Sets the messenger address for the OFT contract.
     * @param _messenger The address of the messenger contract.
     *
     * @dev This function can only be called by the owner of the contract.
     * It allows changing the messenger address to a new one.
     */
    function setMessenger(address _messenger) external;

    /**
     * @notice Internal function to handle the receive on the LayerZero endpoint.
     * @param origin The origin information.
     *  - srcEid: The source chain endpoint ID.
     *  - sender: The sender address from the src chain.
     *  - nonce: The nonce of the LayerZero message.
     * @param guid The unique identifier for the received LayerZero message.
     * @param message The encoded message.
     * @param executor The address of the executor.
     * @param extraData Additional data.
     *
     * @dev This varies from the traditional lzReceive() because the OFT itself is NOT an OApp,
     * and thus we need to validate it comes from the current Messenger contract
     */
    function messagingReceive(
        Origin calldata origin,
        bytes32 guid,
        bytes calldata message,
        address executor,
        bytes calldata extraData
    ) external;
}

contracts/interfaces/IOndoOwner.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import { IInspector } from "./IInspector.sol";
import { IMessenger } from "./IMessenger.sol";
import { IOndoOFT } from "./IOndoOFT.sol";
import { IRateLimiter, RateLimitConfig } from "./IRateLimiter.sol";

/**
 * @title IOndoOwner
 * @notice Interface for the Ondo Owner contract, which manages administrative access control
 * and ownership of various components in the Ondo bridge system.
 */
interface IOndoOwner {
    // @dev Custom error messages
    error CallFailed();
    error ConstructorAddressesZero(address inspector, address messenger, address rateLimiter);
    error OnlyAdminCanUnPause();
    error OnlyPendingOwner(address targetContract, address caller);

    // @dev Events
    event ContractOwnershipTransferStarted(address indexed targetContract, address indexed newOwner);
    event ContractOwnershipTransferClaimed(address indexed targetContract, address indexed newOwner);

    /**
     * @notice Returns the pending owner for a target contract.
     * @param targetContract The address of the target contract.
     * @return The address of the pending owner.
     */
    function pendingOwners(address targetContract) external view returns (address);

    // ------------------- View Functions -------------------
    function inspector() external view returns (IInspector);
    function messenger() external view returns (IMessenger);
    function rateLimiter() external view returns (IRateLimiter);

    // ------------------- Admin -------------------
    /**
     * @notice Allows the super admin to execute arbitrary calls to target contracts.
     * @param targetContract The address of the contract to call.
     * @param data The calldata to pass to the target contract.
     * @return success Boolean indicating if the call was successful.
     * @return result The return data from the call.
     */
    function superCall(
        address targetContract,
        bytes calldata data
    ) external returns (bool success, bytes memory result);

    /**
     * @notice Initiates the transfer of ownership for a target contract.
     * @param targetContract The address of the contract whose ownership is being transferred.
     * @param newOwner The address of the new owner.
     */
    function transferContractOwnership(address targetContract, address newOwner) external;

    /**
     * @notice Claims ownership of a target contract by the pending owner.
     * @param targetContract The address of the contract whose ownership is being claimed.
     */
    function claimContractOwnership(address targetContract) external;

    // ------------------- Inspector -------------------
    /**
     * @notice Sets the global paused state on the Inspector contract.
     * @param paused The state of the global pause.
     */
    function setGlobalPaused(bool paused) external;

    /**
     * @notice Sets the paused state for a specific ID on the Inspector contract.
     * @param id The identifier to set the pause state for.
     * @param paused The state of the pause.
     */
    function setIdPaused(bytes32 id, bool paused) external;

    // ------------------- Messenger -------------------
    /**
     * @notice Sets the Inspector for a Messenger contract.
     * @param inspector The Inspector contract instance to set.
     */
    function setInspector(IInspector inspector) external;

    /**
     * @notice Sets the RateLimiter for a Messenger contract.
     * @param rateLimiter The RateLimiter contract instance to set.
     */
    function setRateLimiter(IRateLimiter rateLimiter) external;

    /**
     * @notice Registers a new token with the Messenger.
     * @param tokenId The unique identifier for the token.
     * @param tokenAddress The address of the token contract.
     * @return oftAddress The address of the newly created OndoOFT contract.
     */
    function registerToken(bytes32 tokenId, address tokenAddress) external returns (address oftAddress);

    /**
     * @notice Deregisters an existing token from the Messenger.
     * @param tokenId The unique identifier for the token to be deregistered.
     */
    function deregisterToken(bytes32 tokenId) external;

    /**
     * @notice Registers a token with an existing OFT contract in the Messenger.
     * @param tokenId The unique identifier for the token.
     * @param tokenAddress The address of the token contract.
     * @param oftAddress The address of the existing OFT contract.
     */
    function registerTokenWithOFT(bytes32 tokenId, address tokenAddress, address oftAddress) external;

    // ------------------- OFT -------------------
    /**
     * @notice Sets the Messenger address for an OndoOFT contract.
     * @param oft The OndoOFT contract instance.
     * @param messenger The address of the Messenger contract.
     */
    function setMessengerOFT(IOndoOFT oft, address messenger) external;

    // ------------------- Rate Limiter -------------------
    /**
     * @notice Sets the Messenger address for a RateLimiter contract.
     * @param rateLimiter The RateLimiter contract instance.
     * @param messenger The address of the Messenger contract.
     */
    function setMessengerRateLimiter(IRateLimiter rateLimiter, address messenger) external;

    /**
     * @notice Configures rate limits for the RateLimiter contract.
     * @param configs An array of RateLimitConfig structs representing the rate limit configurations.
     */
    function configureRateLimits(RateLimitConfig[] calldata configs) external;
}

contracts/interfaces/IRateLimiter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.22;

/**
 * @notice Rate Limit struct.
 * @param amount The current amount tracked against the rate limit.
 * @param lastUpdated Timestamp representing the last time the rate limit was checked or updated.
 * @param limit This represents the maximum allowed amount within a given window.
 * @param window Defines the duration of the rate limiting window.
 */
struct RateLimit {
    uint256 amount;
    uint256 lastUpdated;
    uint256 limit;
    uint256 window;
}

/**
 * @notice Rate Limit Configuration struct.
 * @param remoteEid The destination endpoint id.
 * @param tokenId The identifier for the token.
 * @param outboundLimit This represents the maximum allowed amount within a given window for outflows.
 * @param outboundWindow Defines the duration of the rate limiting window for outflows.
 * @param inboundLimit This represents the maximum allowed amount within a given window for inflows.
 * @param inboundWindow Defines the duration of the rate limiting window for inflows.
 */
struct RateLimitConfig {
    uint32 remoteEid;
    bytes32 tokenId;
    uint256 outboundLimit;
    uint256 outboundWindow;
    uint256 inboundLimit;
    uint256 inboundWindow;
}

/**
 * @title IRateLimiter
 * @notice Interface for the Rate Limiter, which manages rate limits for outflows and inflows of tokens.
 * @dev Indexes the rate limits by Id, can be done with token addresses etc.
 */
interface IRateLimiter {
    // @dev Custom error messages
    error MessengerIdempotent();
    error OnlyMessenger(address caller);
    error RateLimitExceeded();

    // @dev Events
    event MessengerSet(address indexed messenger);
    event RateLimitsSet(RateLimitConfig[] rateLimitConfig);

    // @dev The address of the Messenger contract, which is used to verify the caller in outflow and inflow functions.
    function messenger() external view returns (address);

    /**
     * @notice Sets the Messenger address, which is used to verify the caller in outflow and inflow functions.
     * @param _messenger The address of the Messenger contract.
     */
    function setMessenger(address _messenger) external;

    /**
     * @notice Configures the rate limits for the specified tokenId and destination endpoint id.
     * @param configs An array of `RateLimitConfig` structs representing the rate limit configurations.
     * - `remoteEid`: The destination endpoint id.
     * - `tokenId`: The identifier for the token.
     * - `outboundLimit`: This represents the maximum allowed amount within a given window for outflows.
     * - `outboundWindow`: Defines the duration of the rate limiting window for outflows.
     * - `inboundLimit`: This represents the maximum allowed amount within a given window for inflows.
     * - `inboundWindow`: Defines the duration of the rate limiting window for inflows.
     */
    function configureRateLimits(RateLimitConfig[] calldata configs) external;

    /**
     * @notice Current amount that can be sent to this dst endpoint id for the given rate limit window and tokenId.
     * @param tokenId The identifier for which the rate limit is being checked.
     * @param tokenAddress The address of the token from the corresponding Id.
     * @param remoteEid The remote endpoint id.
     * @return sendable The current amount that can be sent.
     * @return currentOutbound The current amount used for outbound flows.
     * @return receivable The amount that can be received.
     * @return currentInbound The current amount used for inbound flows.
     */
    function getAmountsAvailable(
        bytes32 tokenId,
        address tokenAddress,
        uint32 remoteEid
    ) external view returns (uint256 sendable, uint256 currentOutbound, uint256 receivable, uint256 currentInbound);

    /**
     * @notice Verifies whether the specified amount falls within the rate limit constraints for the targeted
     * endpoint ID. On successful verification, it updates amountInFlight and lastUpdated. If the amount exceeds
     * the rate limit, the operation reverts.
     * @param tokenId The identifier for the token.
     * @param tokenAddress The address of the token from the corresponding Id.
     * @param dstEid The destination endpoint id.
     * @param amount The amount to outflow.
     */
    function outflow(bytes32 tokenId, address tokenAddress, uint32 dstEid, uint256 amount) external;

    /**
     * @notice To be used when you want to calculate your rate limits as a function of net outbound AND inbound.
     * ie. If you move 150 out, and 100 in, your effective inflight should be 50.
     * Does not need to update decay values, as the inflow is effective immediately.
     * @param tokenId The identifier for the token.
     * @param tokenAddress The address of the token from the corresponding Id.
     * @param srcEid The source endpoint id.
     * @param amount The amount to inflow.
     */
    function inflow(bytes32 tokenId, address tokenAddress, uint32 srcEid, uint256 amount) external;
}

contracts/OndoOwner.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.22;

import { AccessControlEnumerable } from "@openzeppelin/contracts/access/extensions/AccessControlEnumerable.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";

import { IOndoOwner, IInspector, IMessenger, IOndoOFT, IRateLimiter, RateLimitConfig } from "./interfaces/IOndoOwner.sol";

/**
 * @title OndoOwner
 * @notice Central administrative contract that manages access control and ownership
 * for the Ondo bridge system components.
 * @dev Implements role-based access control using OpenZeppelin's AccessControlEnumerable
 */
contract OndoOwner is IOndoOwner, AccessControlEnumerable {
    /**
     * @notice Role identifier for Inspector administrators
     * @dev Keccak256 hash of "INSPECTOR_ADMIN"
     */
    bytes32 public constant INSPECTOR_ADMIN = keccak256("INSPECTOR_ADMIN");

    /**
     * @notice Role identifier for Messenger administrators
     * @dev Keccak256 hash of "MESSENGER_ADMIN"
     */
    bytes32 public constant MESSENGER_ADMIN = keccak256("MESSENGER_ADMIN");

    /**
     * @notice Role identifier for Rate Limiter administrators
     * @dev Keccak256 hash of "RATE_LIMITER_ADMIN"
     */
    bytes32 public constant RATE_LIMITER_ADMIN = keccak256("RATE_LIMITER_ADMIN");

    /**
     * @notice Mapping of target contracts to their pending owners
     * @dev Used for the two-step ownership transfer pattern
     */
    mapping(address targetContract => address pendingOwner) public pendingOwners;

    // @dev Contracts owned by this wrapper, for configs to be pushed to.
    IInspector public inspector;
    IMessenger public immutable messenger;
    IRateLimiter public rateLimiter;

    /**
     * @notice Modifier that restricts function access to accounts with the specified role
     * @param role The role identifier required to access the function
     * @dev Also allows accounts with the DEFAULT_ADMIN_ROLE to access the function
     */
    modifier only(bytes32 role) {
        if (!hasRole(role, msg.sender) && !hasRole(DEFAULT_ADMIN_ROLE, msg.sender)) {
            revert AccessControlUnauthorizedAccount(msg.sender, role);
        }
        _;
    }

    /**
     * @notice Constructs the OndoOwner contract with initial administrators
     * @param _inspector Address of the Inspector contract
     * @param _messenger Address of the Messenger contract
     * @param _rateLimiter Address of the RateLimiter contract
     * @param _inspectorAdmin Address to be granted the INSPECTOR_ADMIN role
     * @param _messengerAdmin Address to be granted the MESSENGER_ADMIN role
     * @param _rateLimiterAdmin Address to be granted the RATE_LIMITER_ADMIN role
     * @param _owner Address to be set as the owner and granted the DEFAULT_ADMIN_ROLE
     */
    constructor(
        address _inspector,
        address _messenger,
        address _rateLimiter,
        address _inspectorAdmin,
        address _messengerAdmin,
        address _rateLimiterAdmin,
        address _owner
    ) {
        if (_inspector == address(0) || _messenger == address(0) || _rateLimiter == address(0)) {
            revert ConstructorAddressesZero(_inspector, _messenger, _rateLimiter);
        }

        inspector = IInspector(_inspector);
        messenger = IMessenger(_messenger);
        rateLimiter = IRateLimiter(_rateLimiter);

        _grantRole(INSPECTOR_ADMIN, _inspectorAdmin);
        _grantRole(MESSENGER_ADMIN, _messengerAdmin);
        _grantRole(RATE_LIMITER_ADMIN, _rateLimiterAdmin);
        _grantRole(DEFAULT_ADMIN_ROLE, _owner);
    }

    // ------------------- Admin -------------------

    /**
     * @notice Allows the admin to execute arbitrary calls to target contracts
     * @param _targetContract The address of the contract to call
     * @param _data The calldata to pass to the target contract
     * @return success Boolean indicating if the call was successful
     * @return result The return data from the call
     * @dev This function can only be called by accounts with the DEFAULT_ADMIN_ROLE
     */
    function superCall(
        address _targetContract,
        bytes calldata _data
    ) external only(DEFAULT_ADMIN_ROLE) returns (bool success, bytes memory result) {
        (success, result) = _targetContract.call(_data);
        if (!success) revert CallFailed();

        return (success, result);
    }

    /**
     * @notice Initiates the transfer of ownership for a target contract
     * @param _targetContract The address of the contract whose ownership is being transferred
     * @param _newOwner The address of the new owner
     * @dev This function can only be called by accounts with the DEFAULT_ADMIN_ROLE
     * @dev This is the first step in the two-step ownership transfer pattern
     */
    function transferContractOwnership(address _targetContract, address _newOwner) external only(DEFAULT_ADMIN_ROLE) {
        pendingOwners[_targetContract] = _newOwner;
        emit ContractOwnershipTransferStarted(_targetContract, _newOwner);
    }

    /**
     * @notice Claims ownership of a target contract by the pending owner
     * @param _targetContract The address of the contract whose ownership is being claimed
     * @dev This function can only be called by the pending owner of the target contract
     * @dev This is the second step in the two-step ownership transfer pattern
     */
    function claimContractOwnership(address _targetContract) external {
        address pendingOwner = pendingOwners[_targetContract];
        if (msg.sender != pendingOwner) revert OnlyPendingOwner(_targetContract, msg.sender);
        delete pendingOwners[_targetContract];
        Ownable(_targetContract).transferOwnership(pendingOwner);
        emit ContractOwnershipTransferClaimed(_targetContract, pendingOwner);
    }

    // ------------------- Inspector -------------------

    /**
     * @notice Sets the global paused state on the Inspector contract
     * @param _paused The state of the global pause
     * @dev This function can only be called by accounts with the INSPECTOR_ADMIN role or DEFAULT_ADMIN_ROLE
     */
    function setGlobalPaused(bool _paused) external only(INSPECTOR_ADMIN) {
        // @dev Only the Admin can 'unpause'
        if (!_paused && !hasRole(DEFAULT_ADMIN_ROLE, msg.sender)) revert OnlyAdminCanUnPause();

        inspector.setGlobalPaused(_paused);
    }

    /**
     * @notice Sets the paused state for a specific ID on the Inspector contract
     * @param _id The identifier to set the pause state for
     * @param _paused The state of the pause
     * @dev This function can only be called by accounts with the INSPECTOR_ADMIN role or DEFAULT_ADMIN_ROLE
     */
    function setIdPaused(bytes32 _id, bool _paused) external only(INSPECTOR_ADMIN) {
        // @dev Only the Admin can 'unpause'
        if (!_paused && !hasRole(DEFAULT_ADMIN_ROLE, msg.sender)) revert OnlyAdminCanUnPause();

        inspector.setIdPaused(_id, _paused);
    }

    // ------------------- Messenger -------------------

    /**
     * @notice Sets the Inspector for a Messenger contract
     * @param _inspector The Inspector contract instance to set
     * @dev This function can only be called by accounts with the DEFAULT_ADMIN_ROLE
     */
    function setInspector(IInspector _inspector) external only(DEFAULT_ADMIN_ROLE) {
        inspector = _inspector;
        messenger.setInspector(address(_inspector));
    }

    /**
     * @notice Sets the RateLimiter for a Messenger contract
     * @param _rateLimiter The RateLimiter contract instance to set
     * @dev This function can only be called by accounts with the DEFAULT_ADMIN_ROLE
     */
    function setRateLimiter(IRateLimiter _rateLimiter) external only(DEFAULT_ADMIN_ROLE) {
        rateLimiter = _rateLimiter;
        messenger.setRateLimiter(address(_rateLimiter));
    }

    /**
     * @notice Registers a new token with the Messenger
     * @param _tokenId The unique identifier for the token
     * @param _tokenAddress The address of the token contract
     * @return oftAddress The address of the newly created OndoOFT contract
     * @dev This function can only be called by accounts with the MESSENGER_ADMIN role or DEFAULT_ADMIN_ROLE
     */
    function registerToken(
        bytes32 _tokenId,
        address _tokenAddress
    ) external only(MESSENGER_ADMIN) returns (address oftAddress) {
        oftAddress = messenger.registerToken(_tokenId, _tokenAddress);
    }

    /**
     * @notice Deregisters an existing token from the Messenger
     * @param _tokenId The unique identifier for the token to be deregistered
     *
     * @dev This function can only be called by accounts with the DEFAULT_ADMIN_ROLE
     */
    function deregisterToken(bytes32 _tokenId) external only(DEFAULT_ADMIN_ROLE) {
        messenger.deregisterToken(_tokenId);
    }

    /**
     * @notice Registers a token with an existing OFT contract in the Messenger
     * @param _tokenId The unique identifier for the token
     * @param _tokenAddress The address of the token contract
     * @param _oftAddress The address of the existing OFT contract
     *
     * @dev This function can only be called by accounts with the DEFAULT_ADMIN_ROLE
     */
    function registerTokenWithOFT(
        bytes32 _tokenId,
        address _tokenAddress,
        address _oftAddress
    ) external only(DEFAULT_ADMIN_ROLE) {
        messenger.registerTokenWithOFT(_tokenId, _tokenAddress, _oftAddress);
    }

    // ------------------- OFT -------------------

    /**
     * @notice Sets the Messenger address for an OndoOFT contract
     * @param _oft The OndoOFT contract instance
     * @param _messenger The address of the Messenger contract
     * @dev This function can only be called by accounts with the DEFAULT_ADMIN_ROLE
     */
    function setMessengerOFT(IOndoOFT _oft, address _messenger) external only(DEFAULT_ADMIN_ROLE) {
        _oft.setMessenger(_messenger);
    }

    // ------------------- Rate Limiter -------------------

    /**
     * @notice Sets the Messenger address for a RateLimiter contract
     * @param _rateLimiter The RateLimiter contract instance
     * @param _messenger The address of the Messenger contract
     * @dev This function can only be called by accounts with the DEFAULT_ADMIN_ROLE
     */
    function setMessengerRateLimiter(IRateLimiter _rateLimiter, address _messenger) external only(DEFAULT_ADMIN_ROLE) {
        _rateLimiter.setMessenger(_messenger);
    }

    /**
     * @notice Configures rate limits for the RateLimiter contract
     * @param _configs An array of RateLimitConfig structs representing the rate limit configurations
     * @dev This function can only be called by accounts with the RATE_LIMITER_ADMIN role or DEFAULT_ADMIN_ROLE
     */
    function configureRateLimits(RateLimitConfig[] calldata _configs) external only(RATE_LIMITER_ADMIN) {
        rateLimiter.configureRateLimits(_configs);
    }
}
